      const keyGroups=remoteKeyResults.flatMap(result=>result.status==="fulfilled"?[result.value]:[]);
      const unavailableMembers=remoteKeyResults.flatMap((result,index)=>result.status==="rejected"?[remoteUsers[index]?.nickname||remoteUsers[index]?.username||"알 수 없는 참여자"]:[]);
      const own=ownKeyResult[0]?.status==="fulfilled"?ownKeyResult[0].value:[];
      const keys=keyGroups.flatMap(group=>group.keys);const owners=Object.fromEntries(keyGroups.flatMap(group=>group.keys.map(key=>[key.device_id,group.userId])));
