      const trust:Record<string,PeerIdentityStatus>={};
      for(const key of keys){try{trust[key.device_id]=await peerIdentityStatus(session.username,owners[key.device_id],key)}catch(e){trust[key.device_id]={status:"changed",safetyNumber:"",pinnedIdentityPublicKey:null};setNotice(`참여자 장치 키 검증 실패: ${String(e)}`)}}
      if(requestId!==selectedRequestRef.current)return;
      setPeerKeys(keys);setOwnKeys(own);setPeerTrust(trust);setPeerKeyOwners(owners);
      const partialErrors=[...(unavailableMembers.length?[`${unavailableMembers.join(", ")} 장치 키를 불러오지 못했습니다.`]:[]),...(own.length===0?["현재 계정의 다른 장치 키를 불러오지 못했습니다."]:[])];
      setPeerLoadError(partialErrors.join(" "));
      const page=await getMessages(conversationId,session,{limit:50});const out=await decryptWireMessages(page.messages,conversationId,session,keys,own,trust);
      if(requestId!==selectedRequestRef.current)return;
      setMessages(current=>{const merged=new Map(current.filter(message=>message.conversation_id===conversationId).map(message=>[message.logical_message_id,message]));for(const message of out)merged.set(message.logical_message_id,message);return[...merged.values()].sort((a,b)=>(a.created_at??"").localeCompare(b.created_at??""))});setMessagesHasMore(page.has_more);setPeerLoadState("ready");
