  async function resolveArduinoPort(){const found=await listArduinoPorts();const supported=found.filter(item=>item.supported);setArduinoPorts(found);const selectedPort=arduinoPort.trim();if(selectedPort&&supported.some(item=>item.port===selectedPort))return selectedPort;if(supported.length===1){setArduinoPort(supported[0].port);return supported[0].port}setArduinoPort("");if(supported.length===0)throw new Error("지원되는 Arduino를 USB로 연결한 뒤 다시 찾기를 누르세요.");throw new Error("지원되는 Arduino가 여러 대입니다. 사용할 기기 하나만 USB에 연결한 뒤 다시 찾으세요.")}
  async function finishPhysicalPinSetup(selectedPort:string,setupId:string){setArduinoStatus(`키패드에서 새 PIN 입력 후 ${keypadConfirmKey}, 같은 PIN을 다시 입력 후 ${keypadConfirmKey} 키를 누르세요.`);setNotice("PIN은 앱이 아니라 Arduino 키패드에서 두 번 입력합니다.");let pinKey=await arduinoEnrollPin(selectedPort);try{if(!session)throw new Error("로그인 세션이 없습니다.");await commitArduinoPinProvisioning(session,setupId,pinKey)}finally{pinKey=""}}
